CREATE TABLE "insite"."markouts" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_id"          bigint                   NOT NULL,
  "details"         jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "submitted_by"    text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "idempotency_key" uuid,
  CONSTRAINT "markouts_idempotency_key_key" UNIQUE (idempotency_key),
  CONSTRAINT "markouts_pkey" PRIMARY KEY (id),
  CONSTRAINT "markouts_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE
);

ALTER TABLE "insite"."markouts"
  ENABLE ROW LEVEL SECURITY;

CREATE INDEX idx_markouts_details_gin ON insite.markouts USING gin (details);

CREATE INDEX idx_markouts_job_id ON insite.markouts USING btree (job_id);

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON insite.markouts
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER cleanup_insite_attachment_files
  BEFORE DELETE ON insite.markouts
  FOR EACH ROW
  EXECUTE FUNCTION public.cleanup_insite_attachment_files();
CREATE POLICY "Enable insert for authenticated users" ON "insite"."markouts"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable read access for authenticated users" ON "insite"."markouts"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for authenticated users" ON "insite"."markouts"
  FOR UPDATE
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text))
  WITH CHECK ((auth.role() = 'authenticated'::text));

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "insite"."markouts" TO "anon", "authenticated", "service_role";
